INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1225330, 155408, 30251, '<td valign="top">very nice, I really enjoy how you included the ends of some of the sticks.</td>', 'very nice, I really enjoy how you included the ends of some of the sticks.', '2005-03-14 00:08:59.000000', NULL, 1),
(1225331, 155501, 25464, '<td valign="top">Good idea and good compositions, but laking a little sharpness.</td>', 'Good idea and good compositions, but laking a little sharpness.', '2005-03-14 00:09:01.000000', NULL, 1),
(1225338, 154198, 25464, '<td valign="top">Interesting composition.  I think this could have been better either in color, or with more dramatic contrast.  It looks a bit overall gray.  Very interesting lines though.</td>', 'Interesting composition.  I think this could have been better either in color, or with more dramatic contrast.  It looks a bit overall gray.  Very interesting lines though.', '2005-03-14 00:10:42.000000', NULL, 1),
(1225340, 154747, 30251, '<td valign="top">Great shot, good action freeze.</td>', 'Great shot, good action freeze.', '2005-03-14 00:10:56.000000', NULL, 1),
(1225351, 155591, 30251, '<td valign="top">Nice use of the sky as negative space. Great Compo.</td>', 'Nice use of the sky as negative space. Great Compo.', '2005-03-14 00:12:17.000000', NULL, 1),
(1225352, 155373, 25464, '<td valign="top">BEEEautiful!  Excellent DOF and detail.  Interesting composition and great display of lines - both natural and man made.  If this is not Jacko, he would be proud.</td>', 'BEEEautiful!  Excellent DOF and detail.  Interesting composition and great display of lines - both natural and man made.  If this is not Jacko, he would be proud.', '2005-03-14 00:12:18.000000', NULL, 1),
(1225360, 154860, 33112, '<td valign="top">I''m giving you a 10 for boldness.  You''re gonna need it when the soccer moms see this one.<br/> <br/>My first reaction was that the background was a little too busy....but the brightness of the girl is enough to overcome it....my only problem with it is that the blood looks too painted on.   Strong image though.</td>', 'I''m giving you a 10 for boldness.  You''re gonna need it when the soccer moms see this one. My first reaction was that the background was a little too busy....but the brightness of the girl is enough to overcome it....my only problem with it is that the blood looks too painted on.   Strong image though.', '2005-03-14 00:12:57.000000', NULL, 1),
(1225368, 155099, 30251, '<td valign="top">Good macro work, I like the fuzzy stick vs the bubble in the match heads. It''s cool.</td>', 'Good macro work, I like the fuzzy stick vs the bubble in the match heads. It''s cool.', '2005-03-14 00:14:11.000000', NULL, 1),
(1225369, 155747, 25464, '<td valign="top">This is a nice illustration of implied lines.  The thing I like best is the way it draws your eye in to the faint mountain in the background.  A different time of day might have produced more dramatic light, but a great shot regardless.</td>', 'This is a nice illustration of implied lines.  The thing I like best is the way it draws your eye in to the faint mountain in the background.  A different time of day might have produced more dramatic light, but a great shot regardless.', '2005-03-14 00:14:11.000000', NULL, 1),
(1225374, 155461, 16241, '<td valign="top">awesome!  :)</td>', 'awesome!  :)', '2005-03-14 00:14:52.000000', NULL, 1),
(1225376, 155727, 7291, '<td valign="top">Wow!  This is unbelievable!  This is going into my favorites. - 10</td>', 'Wow!  This is unbelievable!  This is going into my favorites. - 10', '2005-03-14 00:15:07.000000', NULL, 1),
(1225382, 155625, 30251, '<td valign="top">Makes me dizzy . . .</td>', 'Makes me dizzy . . .', '2005-03-14 00:15:48.000000', NULL, 1),
(1225390, 155255, 30251, '<td valign="top">Great use of color, and bokeh.</td>', 'Great use of color, and bokeh.', '2005-03-14 00:16:45.000000', NULL, 1),
(1225391, 155353, 25464, '<td valign="top">This was a good idea that is lacking in execution.  Animal pictures just don''t work very well if the eyes are included in the shot, but you can''t see them.  This shot is just too dark.</td>', 'This was a good idea that is lacking in execution.  Animal pictures just don''t work very well if the eyes are included in the shot, but you can''t see them.  This shot is just too dark.', '2005-03-14 00:16:47.000000', NULL, 1),
(1225399, 154813, 30608, '<td valign="top">Nice capture! Focus on the monkey and the cage is very good. Monkeys like this don''t usually stop for a pose. Good Job!!</td>', 'Nice capture! Focus on the monkey and the cage is very good. Monkeys like this don''t usually stop for a pose. Good Job!!', '2005-03-14 00:18:04.000000', NULL, 1),
(1225400, 154504, 10170, '<td valign="top">Love the lighting and the soft look here, which you have managed to do beautifully without that usual "out of focus" feeling.</td>', 'Love the lighting and the soft look here, which you have managed to do beautifully without that usual "out of focus" feeling.', '2005-03-14 00:18:06.000000', NULL, 1),
