INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1227025, 153757, 14614, '<td valign="top">Ice is not easy to capture and you''ve done a fine job here.  Background is pleasingly blurry and adds the color and punch.</td>', 'Ice is not easy to capture and you''ve done a fine job here.  Background is pleasingly blurry and adds the color and punch.', '2005-03-14 15:13:01.000000', NULL, 1),
(1227026, 155094, 21714, '<td valign="top">Nice one. I like your approach. It''s a great image, but I you could crop from the right to balance the composition by creating an edge to edge tension. Cool stuff.</td>', 'Nice one. I like your approach. It''s a great image, but I you could crop from the right to balance the composition by creating an edge to edge tension. Cool stuff.', '2005-03-14 15:13:22.000000', NULL, 1),
(1227028, 155713, 14614, '<td valign="top">your lighting let you down here -- I do like the play on words.</td>', 'your lighting let you down here -- I do like the play on words.', '2005-03-14 15:14:08.000000', NULL, 1),
(1227029, 154599, 21714, '<td valign="top">This is a beautiful photograph. I like it a lot.</td>', 'This is a beautiful photograph. I like it a lot.', '2005-03-14 15:14:12.000000', NULL, 1),
(1227033, 154862, 21714, '<td valign="top">Very cool image. I like what you have done with those boxes. The colours are amazing and there''s a really nice balance to the whole frame.</td>', 'Very cool image. I like what you have done with those boxes. The colours are amazing and there''s a really nice balance to the whole frame.', '2005-03-14 15:15:34.000000', NULL, 1),
(1227041, 155626, 2490, '<td valign="top">Great shadow shot.  There''s one line of light that bothers me.  8</td>', 'Great shadow shot.  There''s one line of light that bothers me.  8', '2005-03-14 15:20:22.000000', NULL, 1),
