INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1230659, 154860, 34069, '<td valign="top">A rather nasty thought but this image drives it home powerfully.</td>', 'A rather nasty thought but this image drives it home powerfully.', '2005-03-15 23:19:47.000000', NULL, 1),
(1230664, 155743, 32602, '<td valign="top">Lovely. Did you consider cropping to keep make it more symmetrical? Or choose to keep more of the rightside in? Interesting.</td>', 'Lovely. Did you consider cropping to keep make it more symmetrical? Or choose to keep more of the rightside in? Interesting.', '2005-03-15 23:20:30.000000', NULL, 1),
(1230669, 155405, 34069, '<td valign="top">The tall aspect ratio goes well with the subject.  I think B&amp;W is a good choice - it fits the antique feel of the lamps.</td>', 'The tall aspect ratio goes well with the subject.  I think B&W is a good choice - it fits the antique feel of the lamps.', '2005-03-15 23:21:21.000000', NULL, 1),
(1230676, 154396, 30608, '<td valign="top">Looks over processed and no longer natural.</td>', 'Looks over processed and no longer natural.', '2005-03-15 23:22:41.000000', NULL, 1),
(1230677, 155026, 34069, '<td valign="top">Excellent.  One case where a sharpening halo is a GOOD thing.</td>', 'Excellent.  One case where a sharpening halo is a GOOD thing.', '2005-03-15 23:22:55.000000', NULL, 1),
(1230681, 155756, 34069, '<td valign="top">I would have preferred the loop to be lit up a bit brighter but overall I like it.</td>', 'I would have preferred the loop to be lit up a bit brighter but overall I like it.', '2005-03-15 23:24:53.000000', NULL, 1),
(1230683, 155694, 32602, '<td valign="top">Nice idea, a bit more contrast perhaps?</td>', 'Nice idea, a bit more contrast perhaps?', '2005-03-15 23:25:27.000000', NULL, 1),
(1230684, 154438, 34069, '<td valign="top">Great color.</td>', 'Great color.', '2005-03-15 23:25:45.000000', NULL, 1),
