(1232403, 155481, 31213, '<td valign="top">I would have liked a little more light on your subject.  Nice DOF.</td>', 'I would have liked a little more light on your subject.  Nice DOF.', '2005-03-16 14:04:25.000000', NULL, 1),
(1232407, 154727, 32767, '<td valign="top">This is a little bland across the board. It''s not a terribly interesting subject so I would have tried to liven it up a bit....maybe a different composition for starters.</td>', 'This is a little bland across the board. It''s not a terribly interesting subject so I would have tried to liven it up a bit....maybe a different composition for starters.', '2005-03-16 14:05:44.000000', NULL, 1),
(1232408, 155455, 31213, '<td valign="top">Teh cloud is overexposed.  Interesting composition but a lot of people will complain about the cant''ed camera.  People usually like to see flat horizon lines.</td>', 'Teh cloud is overexposed.  Interesting composition but a lot of people will complain about the cant''ed camera.  People usually like to see flat horizon lines.', '2005-03-16 14:05:51.000000', NULL, 1),
