(1233973, 155747, 19035, '<td valign="top">Upping my score to a 7 after a second look, a very beautiful and serene photo.</td>', 'Upping my score to a 7 after a second look, a very beautiful and serene photo.', '2005-03-17 06:14:32.000000', NULL, 1),
(1233976, 154873, 19035, '<td valign="top">Good Luck to you, any photo that includes the american flag always takes a hit in this international group - I know Ive tried myself, nice crop and composition.</td>', 'Good Luck to you, any photo that includes the american flag always takes a hit in this international group - I know Ive tried myself, nice crop and composition.', '2005-03-17 06:15:45.000000', NULL, 1),
